def assign_label(category):
    """
    GTDB R220 ncbi_genome_category values:
      "none"                     → isolate = CULTURED   (1)
      "derived from metagenome"  → MAG     = UNCULTURED (0)
      "derived from single cell" → SAG     = UNCULTURED (0)
       NaN                       → unknown → drop
    """
    if pd.isna(category):
        return None  # drop — truly unknown origin

    category = str(category).lower().strip()

    if category == 'none':
        return 1   # ✅ standard isolate = CULTURED
    elif 'metagenome' in category or 'single cell' in category:
        return 0   # ❌ UNCULTURED
    else:
        return None  # drop any other unexpected values

gtdb['label'] = gtdb['ncbi_genome_category'].apply(assign_label)

# Drop truly unknown rows
before = len(gtdb)
gtdb   = gtdb.dropna(subset=['label'])
gtdb['label'] = gtdb['label'].astype(int)
after  = len(gtdb)

print(f"Rows before filtering : {before:,}")
print(f"Rows after  filtering : {after:,}")
