# ============================================================
# CELL 7 — Parse taxonomy string into separate columns
# ============================================================
# The gtdb_taxonomy column looks like:
# "d__Bacteria;p__Firmicutes;c__Bacilli;o__Lactobacillales;f__..."

def parse_taxonomy(tax_string):
    """Splits GTDB taxonomy string into a dictionary."""
    result = {
        'domain': None, 'phylum': None, 'class': None,
        'order':  None, 'family': None, 'genus': None, 'species': None
    }

    if pd.isna(tax_string):
        return result

    prefixes = {
        'd__': 'domain', 'p__': 'phylum', 'c__': 'class',
        'o__': 'order',  'f__': 'family', 'g__': 'genus', 's__': 'species'
    }

    parts = str(tax_string).split(';')
    for part in parts:
        part = part.strip()
        for prefix, col in prefixes.items():
            if part.startswith(prefix):
                value = part[len(prefix):].strip()
                result[col] = value if value else None

    return result

print("⚙️  Parsing taxonomy strings (this takes ~30 seconds)...")
tax_df = gtdb['gtdb_taxonomy'].apply(parse_taxonomy).apply(pd.Series)
gtdb = pd.concat([gtdb.drop('gtdb_taxonomy', axis=1), tax_df], axis=1)

print("✅ Taxonomy parsed!")
