# ============================================================
# CELL 28 — First: Train longer MLP (fix the epoch issue)
# ============================================================
# Best epoch was 50 (last epoch) → model hadn't converged yet
# We retrain for 100 epochs to get the true best model

print("🔄 Retraining MLP for 100 epochs to reach full convergence...\n")

# Reinitialize fresh model
model2 = CulturabilityMLP(input_dim).to(device)
optimizer2 = optim.Adam(model2.parameters(), lr=1e-3, weight_decay=1e-4)
scheduler2 = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer2, mode='min', patience=7, factor=0.5
)

N_EPOCHS2 = 100
best_val_loss2 = float('inf')
best_state2 = None
history2 = {'train_loss': [], 'val_loss': [], 'train_acc': [], 'val_acc': []}

print(f"{'Epoch':>6} {'Train Loss':>12} {'Val Loss':>10} {'Train Acc':>11} {'Val Acc':>9} {'LR':>10}")
print("─" * 65)

for epoch in range(1, N_EPOCHS2 + 1):

    # Training
    model2.train()
    train_loss, train_correct, train_total = 0, 0, 0
    for X_batch, y_batch in train_loader:
        optimizer2.zero_grad()
        preds = model2(X_batch)
        loss  = criterion(preds, y_batch)
        loss.backward()
        optimizer2.step()
        train_loss    += loss.item() * len(y_batch)
        train_correct += ((preds >= 0.5).float() == y_batch).sum().item()
        train_total   += len(y_batch)

    # Validation
    model2.eval()
    val_loss, val_correct, val_total = 0, 0, 0
    with torch.no_grad():
        for X_batch, y_batch in val_loader:
            preds = model2(X_batch)
            loss  = criterion(preds, y_batch)
            val_loss    += loss.item() * len(y_batch)
            val_correct += ((preds >= 0.5).float() == y_batch).sum().item()
            val_total   += len(y_batch)

    tl = train_loss / train_total
    vl = val_loss   / val_total
    ta = train_correct / train_total * 100
    va = val_correct   / val_total   * 100
    lr = optimizer2.param_groups[0]['lr']

    history2['train_loss'].append(tl)
    history2['val_loss'].append(vl)
    history2['train_acc'].append(ta)
    history2['val_acc'].append(va)

    if vl < best_val_loss2:
        best_val_loss2 = vl
        best_state2    = {k: v.clone() for k, v in model2.state_dict().items()}
        best_epoch2    = epoch

    scheduler2.step(vl)

    if epoch % 10 == 0 or epoch == 1:
        marker = ' ⭐' if vl == best_val_loss2 else ''
        print(f"{epoch:>6}  {tl:>12.4f}  {vl:>10.4f}  {ta:>10.2f}%  {va:>8.2f}%  {lr:>10.6f}{marker}")

print(f"\n✅ Best model at epoch {best_epoch2} (val_loss={best_val_loss2:.4f})")
model2.load_state_dict(best_state2)
