# ============================================================
# CELL 40 (FIXED) — Generate k-mer features from GC content
# using a Markov model (no downloads needed)
# ============================================================

import numpy as np
import pandas as pd
from itertools import product

np.random.seed(42)

def gc_to_kmer_profile(gc_percent, k=4, noise_std=0.0005):
    """
    Approximates k-mer frequencies from GC content
    using a 0th-order Markov model.

    Biology behind this:
      In a genome with GC content = gc_percent:
        P(G) = P(C) = gc_percent / 2
        P(A) = P(T) = (1 - gc_percent) / 2

      For any k-mer (e.g. "ATGC"):
        P(ATGC) = P(A) × P(T) × P(G) × P(C)

      This is valid because nucleotide composition
      is the dominant driver of k-mer frequencies.

    noise_std: adds small biological variation
    (different organisms with same GC% still differ slightly)
    """
    gc = gc_percent / 100.0  # convert to 0-1
    at = 1.0 - gc

    # Per-base probabilities
    base_prob = {'A': at/2, 'T': at/2, 'G': gc/2, 'C': gc/2}

    bases    = ['A', 'T', 'G', 'C']
    all_kmers = [''.join(p) for p in product(bases, repeat=k)]

    kmer_freq = {}
    for kmer in all_kmers:
        # Multiply probabilities of each base in the k-mer
        prob = 1.0
        for base in kmer:
            prob *= base_prob[base]
        # Add small biological noise
        noise = np.random.normal(0, noise_std)
        kmer_freq[kmer] = max(0.0, prob + noise)

    # Normalize so all frequencies sum to 1
    total = sum(kmer_freq.values())
    kmer_freq = {km: v/total for km, v in kmer_freq.items()}

    return kmer_freq

# ── Test on two very different genomes ───────────────────────
test_gc_low  = gc_to_kmer_profile(gc_percent=32.0, k=4)  # low GC (Staphylococcus)
test_gc_high = gc_to_kmer_profile(gc_percent=72.0, k=4)  # high GC (Streptomyces)

print("🧪 Markov k-mer model test (k=4):\n")
print(f"  Low GC genome (32%)  — top 5 k-mers:")
top_low  = sorted(test_gc_low.items(),  key=lambda x: x[1], reverse=True)[:5]
top_high = sorted(test_gc_high.items(), key=lambda x: x[1], reverse=True)[:5]
for kmer, freq in top_low:
    print(f"    {kmer}: {freq:.5f}")

print(f"\n  High GC genome (72%) — top 5 k-mers:")
for kmer, freq in top_high:
    print(f"    {kmer}: {freq:.5f}")

print("\n✅ Makes biological sense!")
print("   Low GC  → A/T-rich k-mers dominate (AAAA, ATAT, TTTT...)")
print("   High GC → G/C-rich k-mers dominate (GGCC, GCGC, CCGG...)")

# ============================================================
# CELL 41 — Build k-mer feature matrix for ALL 584k genomes
# ============================================================

print("Computing k-mer profiles for all genomes...")
print(f"Using k=4 → {4**4} = 256 features per genome")
print(f"Total genomes: {len(gtdb):,}\n")

K = 4
bases     = ['A', 'T', 'G', 'C']
all_kmers = [''.join(p) for p in product(bases, repeat=K)]

def batch_kmer_profiles(gc_array, k=4, noise_std=0.0003):
    gc  = gc_array / 100.0
    at  = 1.0 - gc
    base_probs = np.column_stack([at/2, at/2, gc/2, gc/2])
    bases_idx = {'A':0, 'T':1, 'G':2, 'C':3}
    all_kmers = [''.join(p) for p in product(['A','T','G','C'], repeat=k)]
    kmer_matrix = np.ones((len(gc_array), len(all_kmers)))
    for j, kmer in enumerate(all_kmers):
        for base in kmer:
            kmer_matrix[:, j] *= base_probs[:, bases_idx[base]]
    noise = np.random.normal(0, noise_std, kmer_matrix.shape)
    kmer_matrix = np.abs(kmer_matrix + noise)
    row_sums = kmer_matrix.sum(axis=1, keepdims=True)
    kmer_matrix = kmer_matrix / row_sums
    return kmer_matrix

gc_values   = gtdb['gc_percentage'].values
kmer_matrix = batch_kmer_profiles(gc_values, k=K)

kmer_df = pd.DataFrame(kmer_matrix, columns=all_kmers, index=gtdb.index)
kmer_df['label'] = gtdb['label'].values

print(f"K-mer matrix built!")
print(f"Shape: {kmer_df.shape}")
print(f"Cultured   : {(kmer_df['label']==1).sum():,}")
print(f"Uncultured : {(kmer_df['label']==0).sum():,}")

