phylum_enc = gtdb.iloc[idx]['phylum_encoded'].values.reshape(-1,1)
X_meta_full = np.hstack([X_meta, phylum_enc])   # same as FEATURES

X_combined = np.hstack([X_meta_full, X_kmer])   # metadata + k-mers

print(f"Feature matrix sizes (on {SAMPLE_SIZE:,} genome sample):")
