# ============================================================
# CELL 46 — Master prediction function
# ============================================================
# This function takes genome features and returns ALL predictions
# Used by both the evaluation code and the Gradio interface

def predict_all_conditions(
    genome_size, gc_percentage, protein_count,
    contig_count, n50_contigs, ambiguous_bases,
    checkm_completeness, checkm_contamination,
    trna_aa_count, phylum_name
):
    """
    Master prediction function.

    Input : 10 genomic features + phylum name (string)
    Output: dictionary with all predictions + probabilities

    This is the core of your interface.
    """
    # Encode phylum
    try:
        phylum_enc = le_phylum.transform([phylum_name])[0]
    except ValueError:
        phylum_enc = le_phylum.transform(['Unknown'])[0]

    # Build feature vector (same order as FEATURES list)
    feature_values = [
        genome_size, gc_percentage, protein_count,
        contig_count, n50_contigs, ambiguous_bases,
        checkm_completeness, checkm_contamination,
        trna_aa_count, phylum_enc
    ]

    X_input = np.array(feature_values).reshape(1, -1)
    X_input_scaled = scaler.transform(X_input)

    results = {}

    # ── 1. Culturability ──────────────────────────────────────
    cult_proba = rf_model.predict_proba(X_input_scaled)[0][1]
    results['culturability'] = {
        'probability' : float(cult_proba),
        'label'       : 'Likely Culturable' if cult_proba >= 0.5
                        else 'Likely Unculturable',
        'confidence'  : 'High' if abs(cult_proba - 0.5) > 0.3
                        else 'Medium' if abs(cult_proba - 0.5) > 0.1
                        else 'Low'
    }

    # ── 2. Growth conditions ──────────────────────────────────
    cond_labels = {
        'temp_class'  : 'Temperature',
        'oxygen_class': 'Oxygen Requirement',
        'ph_class'    : 'pH Preference',
        'media_class' : 'Recommended Media'
    }

    for col, label in cond_labels.items():
        model   = condition_models[col]
        encoder = condition_encoders[col]

        proba_array = model.predict_proba(X_input_scaled)[0]
        pred_idx    = np.argmax(proba_array)
        pred_label  = encoder.classes_[pred_idx]
        confidence  = float(proba_array[pred_idx]) * 100

        # All class probabilities
        class_probas = {
            encoder.classes_[i]: float(proba_array[i]) * 100
            for i in range(len(encoder.classes_))
        }

        results[col] = {
            'prediction' : pred_label,
            'confidence' : confidence,
            'all_probs'  : class_probas
        }

    # ── 3. Suggested culture conditions summary ───────────────
    temp_map = {
        'Psychrophile'      : '4–15°C',
        'Mesophile'         : '25–40°C',
        'Thermophile'       : '45–70°C',
        'Hyperthermophile'  : '80–121°C'
    }
    ph_map = {
        'Acidophile'  : 'pH 2.5–5.5',
        'Neutrophile' : 'pH 6.5–8.5',
        'Alkaliphile' : 'pH 8.5–11.0'
    }

    results['summary'] = {
        'temperature_range' : temp_map.get(
            results['temp_class']['prediction'], 'Unknown'),
        'ph_range'          : ph_map.get(
            results['ph_class']['prediction'], 'Unknown'),
        'oxygen'            : results['oxygen_class']['prediction'],
        'media'             : results['media_class']['prediction'],
        'culturable'        : results['culturability']['label'],
        'cult_probability'  : f"{cult_proba*100:.1f}%"
    }

    return results

# ── Test on a known organism ──────────────────────────────────
print("🧪 Testing prediction function on E. coli-like genome:\n")

