    # ── Wire predict ──────────────────────────────────────────
    predict_btn.click(
        fn      = predict_from_name,
        inputs  = [name_input],
        outputs = [report_output, chart_output]
    )
    name_input.submit(   # pressing Enter also works
        fn      = predict_from_name,
        inputs  = [name_input],
        outputs = [report_output, chart_output]
    )

    # ── Wire example buttons ──────────────────────────────────
    for btn, name in [
        (ex1, "Escherichia coli"),
        (ex2, "Staphylococcus aureus"),
        (ex3, "Bacillus subtilis"),
        (ex4, "Streptomyces griseus"),
        (ex5, "Lactobacillus acidophilus"),
    ]:
        btn.click(
            fn      = lambda n=name: (
                n,
                *predict_from_name(n)
            ),
            inputs  = [],
            outputs = [name_input, report_output, chart_output]
        )

