NUMERIC_COLS = ['genome_size','gc_percentage','protein_count','coding_bases',
                'contig_count','n50_contigs','ambiguous_bases',
                'checkm_completeness','checkm_contamination','trna_aa_count']
NUMERIC_FEATURES = [c for c in NUMERIC_COLS if c != 'coding_bases']

le_phylum = LabelEncoder()
gtdb['phylum_encoded'] = le_phylum.fit_transform(gtdb['phylum'].fillna('Unknown'))
FEATURES = NUMERIC_FEATURES + ['phylum_encoded']

