"""5. Reload original MLP architecture (needed for K5 comparison)"""

class CulturabilityMLP(nn.Module):
    def __init__(self, input_dim):
        super().__init__()
        self.network = nn.Sequential(
            nn.Linear(input_dim, 256), nn.BatchNorm1d(256), nn.ReLU(), nn.Dropout(0.3),
            nn.Linear(256, 128),       nn.BatchNorm1d(128), nn.ReLU(), nn.Dropout(0.3),
            nn.Linear(128, 64),        nn.BatchNorm1d(64),  nn.ReLU(), nn.Dropout(0.2),
            nn.Linear(64, 32),         nn.ReLU(),
            nn.Linear(32, 1),          nn.Sigmoid()
        )
    def forward(self, x):
        return self.network(x).squeeze(1)

device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
print(f"✅ MLP class defined | Device: {device}")

"""now we add the kmers feature and train our model on the new full data"""

# ============================================================
# Cell K1 (FIXED) — Regenerate k-mers directly from gtdb
# No CSV loading needed!
# ============================================================

import numpy as np
from itertools import product

K         = 4
bases     = ['A','T','G','C']
all_kmers = [''.join(p) for p in product(bases, repeat=K)]

def batch_kmer_profiles(gc_array, k=4, noise_std=0.0003):
    gc  = gc_array / 100.0
    at  = 1.0 - gc
    base_probs = np.column_stack([at/2, at/2, gc/2, gc/2])
    bases_idx  = {'A':0,'T':1,'G':2,'C':3}
    all_kmers_ = [''.join(p) for p in product(['A','T','G','C'], repeat=k)]
    kmer_mat   = np.ones((len(gc_array), len(all_kmers_)))
    for j, kmer in enumerate(all_kmers_):
        for base in kmer:
            kmer_mat[:, j] *= base_probs[:, bases_idx[base]]
    noise    = np.random.normal(0, noise_std, kmer_mat.shape)
    kmer_mat = np.abs(kmer_mat + noise)
    kmer_mat = kmer_mat / kmer_mat.sum(axis=1, keepdims=True)
    return kmer_mat

print("⚙️  Regenerating k-mer matrix from GC content...")
np.random.seed(42)
gc_values   = gtdb['gc_percentage'].values
kmer_matrix = batch_kmer_profiles(gc_values, k=K)
print(f"✅ K-mer matrix ready: {kmer_matrix.shape}")

# Stack with metadata
X_meta     = gtdb[FEATURES].fillna(gtdb[FEATURES].median()).values
X_combined = np.hstack([X_meta, kmer_matrix])

print(f"\n   Original features : {X_meta.shape[1]}")
print(f"   K-mer features    : {kmer_matrix.shape[1]}")
print(f"   Combined          : {X_combined.shape[1]}")
print(f"   Total genomes     : {X_combined.shape[0]:,}")

from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split

y = gtdb['label'].values

# EXACT same random_state=42 as original → fair comparison
X_temp_c, X_test_c, y_temp_c, y_test_c = train_test_split(
    X_combined, y, test_size=0.15, random_state=42, stratify=y)
X_train_c, X_val_c, y_train_c, y_val_c = train_test_split(
    X_temp_c, y_temp_c, test_size=0.176, random_state=42, stratify=y_temp_c)

scaler_combined  = StandardScaler()
X_train_c_sc = scaler_combined.fit_transform(X_train_c)
X_val_c_sc   = scaler_combined.transform(X_val_c)
X_test_c_sc  = scaler_combined.transform(X_test_c)

print(f"✅ Train: {X_train_c.shape[0]:,} | Val: {X_val_c.shape[0]:,} | Test: {X_test_c.shape[0]:,}")

import joblib
joblib.dump(scaler_combined, SAVE_DIR + 'scaler_combined.pkl')
print("✅ Scaler saved!")

from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score, f1_score, roc_auc_score

# ── New RF with k-mers ────────────────────────────────────────
print("🌲 Training RF on 266 features (10 metadata + 256 k-mers)...")

rf_combined = RandomForestClassifier(
    n_estimators=500,        # same as original
    max_depth=20,            # same as original
    min_samples_leaf=5,      # same as original
    class_weight='balanced', # same as original
    random_state=42,         # same as original
    n_jobs=-1
)
rf_combined.fit(X_train_c_sc, y_train_c)
print("✅ Done!\n")

# ── Evaluate both on validation set ──────────────────────────
# Original RF (10 features)
