y_proba_new  = rf_combined.predict_proba(X_val_c_sc)[:,1]

print("=" * 55)
print(f"  {'Model':<30} {'Acc':>8} {'F1':>8} {'AUC':>8}")
print("─" * 55)

for name, yp, ypr in [
    ('RF — 10 features (original)', y_pred_orig, y_proba_orig),
    ('RF — 266 features (+k-mers)', y_pred_new,  y_proba_new),
]:
    acc = accuracy_score(y_val, yp)  * 100
    f1  = f1_score(y_val, yp, average='macro') * 100
    auc = roc_auc_score(y_val, ypr)
